    let midX = (x1 + x2) / 2;
    let midY = (y1 + y2) / 2;

    let randomSize = p.random(20, 60);
    let randomShape = p.floor(p.random(0, 3));

    switch (randomShape) {
      case 0:
        p.fill(255, 0, 0);
        p.ellipse(midX, midY, randomSize, randomSize);
        break;
      case 1:
        p.fill(0, 0, 255);
        p.rect(midX - randomSize / 2, midY - randomSize / 2, randomSize, randomSize);
        break;
