  p.noStroke();
};

p.draw = function() {
  p.background(0, 50); // Create a clearing effect with mild persistence

  if (globals.handtracking.results.landmarks && globals.handtracking.results.landmarks.length > 0) {
    globals.handtracking.results.landmarks.forEach(hand => {
      const centerX = hand[9].x * globals.width; // Using the middle finger tip to place shapes
      const centerY = hand[9].y * globals.height;

      shapes.push(createBlob(centerX, centerY));
    });

    shapes.forEach((shape, index) => {
      p.fill(shape.color, shape.alpha);
      p.beginShape();
      for (let angle = 0; angle < p.TWO_PI; angle += 0.1) {
        const offset = shape.offset - angle * 10; // Unique Perlin noise offset for blobby undulation
        const r = shape.size / 2 + p.noise(offset) * 25; // Amplitude of the undulation
        const x = shape.x + r * p.cos(angle);
        const y = shape.y + r * p.sin(angle);
        p.vertex(x, y);
      }
      p.endShape(p.CLOSE);
      shape.alpha -= 5;
      shape.offset += 0.05;

      // Remove shape once it has completely faded
      if (shape.alpha <= 0) {
        shapes.splice(index, 1);
      }
    });
  }
};

function createBlob(x, y) {
  return {
    x: x,
    y: y,
    size: p.random(30, 70),
    color: p.color(p.random(255), p.random(255), p.random(255)),
    alpha: 255,
    offset: p.random(1000)
  };
}
